   try{Bundle b=getContentResolver().call(Uri.parse("content://"+GOOGLE),"status",null,null);if(b!=null&&!b.containsKey("error")){JSONObject g=new JSONObject(b.getString("json"));n.googleAvailable=true;n.gmail=g.optBoolean("connected");n.youtube=g.optBoolean("youtubeConnected");n.controls=g.optBoolean("youtubeControls");}}catch(Exception ignored){}
