 void updateLabels(){if(connectionAction!=null){connectionAction.setEnabled(snap.ready);connectionAction.setText(snap.ready?(snap.service?"Pause connection":"Resume connection"):"Checking connection…");}if(!snap.ready){if(connection!=null)connection.setText("Checking…");return;}if(connection!=null)connection.setText(!snap.service?"Paused":!snap.paired?"Setup needed":snap.recent?"Connected":snap.bluetooth?"Calls connected":"Ready for S2");if(linkDetails!=null)linkDetails.setText(snap.service?(snap.wifi.startsWith("Private Wi-Fi ready")?"Private Wi-Fi ready":snap.wifi):"Automatic link paused");set("calls",snap.bluetooth?"Bluetooth calling connected":"Bluetooth calling not connected");set("camera",snap.photos+" photos · "+snap.videos+" videos");set("library",snap.count+" apps · "+snap.stored+" stored");set("google",snap.gmail&&snap.youtube?"Accounts connected":"Open to check accounts");set("gmail",snap.gmail?"Account connected":"Connect account");set("youtube",snap.youtube?(snap.controls?"Account controls enabled":"Read-only account"):"Connect account");set("music",snap.music);set("wifi",snap.wifi);set("bluetooth",snap.bluetooth?"Calling connected":"Not connected");set("cameraDetails",snap.photos+" photos · "+snap.videos+" videos received\nPhotos & videos: Pictures / Galaxy S2\n\n"+snap.camera);set("video", "Playback: "+snap.video);set("location",snap.location);set("web",snap.service?"Compatibility service running":"Connection paused");set("diagnostics","Connection: "+(snap.service?"running":"paused")+"\nPairing: "+(snap.paired?"configured":"missing")+"\nGoogle: "+(snap.googleAvailable?"available":"unavailable")+"\nVideo: "+snap.video+"\nMusic: "+snap.music+"\nWi-Fi: "+snap.wifi+"\nLibrary: "+snap.stored+" / "+snap.count+" stored");if(libraryCount!=null)libraryCount.setText(snap.count+" apps");}
