 void importChanged(LibraryImport.State s){if(s==null||isDestroyed())return;if(importStatus!=null)importStatus.setText(s.message);if(s.phase.equals("confirm")&&(importDialog==null||!importDialog.isShowing())){String d="Version "+s.item.optString("version")+" · "+android.text.format.Formatter.formatFileSize(this,s.file.length());if(s.old!=null)d+="\nReplaces stored version "+s.old.optString("version")+".";if(s.old!=null&&!s.old.optString("signerSha256").equals(s.item.optString("signerSha256")))d+="\nDifferent signing certificate; it cannot update the installed app.";importDialog=new MaterialAlertDialogBuilder(this).setTitle(s.item.optString("name")).setMessage(d).setPositiveButton(s.old==null?"Add to library":"Replace stored version",(x,w)->importer.save()).setNegativeButton("Cancel",(x,w)->importer.cancel()).setOnCancelListener(x->importer.cancel()).show();}else if(s.phase.equals("done")){toast("Added. Refresh the Store on the S2.");importer.acknowledge();load();handler.postDelayed(()->{if(page.equals("library"))show("library");},700);}else if(s.phase.equals("error")){new MaterialAlertDialogBuilder(this).setTitle("Could not add APK").setMessage(s.message).setPositiveButton("OK",(x,w)->importer.acknowledge()).show();}}
